<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { ElMessage } from "element-plus";
import { createPickWave, createWarehouseTask, generateWarehouseTasks, listPickWaves, listWarehouseTasks, releasePickWave, transitionWarehouseTask } from "../../api/inventory-advanced";
import { listMasterData } from "../../api/master-data";
import { labelOf, sourceTypeLabels, statusLabel, tagTypeOf } from "../../utils/labels";
type Row = Record<string, any>;
const tasks = ref<Row[]>([]); const waves = ref<Row[]>([]); const warehouses = ref<Row[]>([]); const materials = ref<Row[]>([]); const selectedTaskIds = ref<string[]>([]); const waveWarehouseId = ref(""); const loading = ref(false); const saving = ref(false); const exceptionSaving = ref(false); const activeTab = ref("tasks"); const createTaskVisible = ref(false); const exceptionVisible = ref(false); const exceptionTask = ref<Row | null>(null); const exceptionReason = ref(""); const taskFilters = ref({ source_type: "", task_type: "", warehouse_id: "", status: "" });
const form = ref({ task_type: "pick", warehouse_id: "", material_id: "", planned_quantity: 0, priority: 50, serial_tracking: false }); const sourceForm = ref({ source_type: "purchase_receipt", source_id: "", serial_tracking: false });
const exceptions = computed(() => tasks.value.filter((item) => item.status === "exception")); const taskTypeLabels: Record<string, string> = { receiving: "收货", putaway: "上架", pick: "拣货", pack: "打包", check: "复核", count: "盘点", move: "移库" }; const taskStatusLabels: Record<string, string> = { ready: "待执行", assigned: "已分配", in_progress: "进行中", completed: "已完成", exception: "异常", cancelled: "已取消" };
const waveTaskOptions = computed(() => tasks.value.filter((item) => item.task_type === "pick" && ["ready", "assigned"].includes(item.status) && (!waveWarehouseId.value || String(item.warehouse_id) === waveWarehouseId.value)));
function taskTypeLabel(value: unknown) { return labelOf(taskTypeLabels, value); } function warehouseLabel(value: unknown) { const warehouse = warehouses.value.find((item) => String(item.id) === String(value)); return warehouse ? `${warehouse.code} · ${warehouse.name}` : labelOf({}, value); } function yesNoTag(value: unknown) { return value ? "success" : "info"; } function completedLabel(row: Row) { return Number(row.completed_quantity || 0) >= Number(row.planned_quantity || 0) && Number(row.planned_quantity || 0) > 0 ? "是" : "否"; }
function unwrap(response: any) { if (response?.data?.code !== 0) throw new Error(response?.data?.msg || "WMS 接口失败"); return response.data.data; }
async function load() { loading.value = true; try { const filters = taskFilters.value; const [taskResponse, waveResponse, warehouseResponse, materialResponse] = await Promise.all([listWarehouseTasks({ source_type: filters.source_type || undefined, task_type: filters.task_type || undefined, warehouse_id: filters.warehouse_id || undefined, status: filters.status || undefined }), listPickWaves(), listMasterData("warehouses"), listMasterData("materials")]); tasks.value = (unwrap(taskResponse)?.items || []).sort((left: Row, right: Row) => String(right.created_at || "").localeCompare(String(left.created_at || ""))); waves.value = unwrap(waveResponse)?.items || []; warehouses.value = unwrap(warehouseResponse)?.items || []; materials.value = unwrap(materialResponse)?.items || []; } catch (error) { ElMessage.error(error instanceof Error ? error.message : "WMS 数据加载失败"); } finally { loading.value = false; } }
function resetTaskFilters() { taskFilters.value = { source_type: "", task_type: "", warehouse_id: "", status: "" }; void load(); }
function openCreateTask() { form.value = { task_type: "pick", warehouse_id: "", material_id: "", planned_quantity: 0, priority: 50, serial_tracking: false }; createTaskVisible.value = true; }
async function save() { if (!form.value.warehouse_id) return ElMessage.warning("请先选择仓库"); saving.value = true; try { unwrap(await createWarehouseTask({ ...form.value, material_id: form.value.material_id || undefined })); ElMessage.success("作业任务已创建"); createTaskVisible.value = false; await load(); } catch (error) { ElMessage.error(error instanceof Error ? error.message : "任务创建失败"); } finally { saving.value = false; } }
async function move(row: Row, status: string) { try { unwrap(await transitionWarehouseTask(String(row.id), { status, completed_quantity: status === "completed" ? row.planned_quantity : undefined, serial_numbers: [] })); await load(); } catch (error) { ElMessage.error(error instanceof Error ? error.message : "任务状态更新失败"); } }
function openException(row: Row) { exceptionTask.value = row; exceptionReason.value = row.exception_reason || ""; exceptionVisible.value = true; }
async function submitException() {
  const reason = exceptionReason.value.trim();
  if (!reason || !exceptionTask.value) return ElMessage.warning("请输入异常原因");
  exceptionSaving.value = true;
  try { unwrap(await transitionWarehouseTask(String(exceptionTask.value.id), { status: "exception", exception_reason: reason })); ElMessage.success("异常已标记"); exceptionVisible.value = false; await load(); } catch (error) { ElMessage.error(error instanceof Error ? error.message : "任务异常登记失败"); } finally { exceptionSaving.value = false; }
}
async function createWave() { if (!waveWarehouseId.value || !selectedTaskIds.value.length) return ElMessage.warning("请选择仓库和至少一个拣货任务"); try { unwrap(await createPickWave({ warehouse_id: waveWarehouseId.value, task_ids: selectedTaskIds.value })); selectedTaskIds.value = []; await load(); } catch (error) { ElMessage.error(error instanceof Error ? error.message : "拣货波次创建失败"); } }
function changeWaveWarehouse(value: string) { waveWarehouseId.value = value; const availableIds = new Set(waveTaskOptions.value.map((item) => String(item.id))); selectedTaskIds.value = selectedTaskIds.value.filter((id) => availableIds.has(id)); }
async function releaseWave(row: Row) { try { unwrap(await releasePickWave(String(row.id))); await load(); } catch (error) { ElMessage.error(error instanceof Error ? error.message : "拣货波次发布失败"); } }
async function generateFromDocument() { if (!sourceForm.value.source_id.trim()) return ElMessage.warning("请输入来源单据号或 ID"); try { unwrap(await generateWarehouseTasks(sourceForm.value.source_type, sourceForm.value.source_id.trim(), sourceForm.value.serial_tracking)); await load(); } catch (error) { ElMessage.error(error instanceof Error ? error.message : "自动生成作业失败"); } }
function toggleTask(row: Row, checked: boolean) { const id = String(row.id); selectedTaskIds.value = checked ? [...new Set([...selectedTaskIds.value, id])] : selectedTaskIds.value.filter((item) => item !== id); }
onMounted(load);
</script>
<template>
  <section class="page-stack"><header class="page-heading"><div><small>WMS EXECUTION</small><h1>仓库作业中心</h1><p>统一管理收货、上架、拣货、复核和异常任务，并支持拣货波次。</p></div><el-button :loading="loading" @click="load">刷新</el-button></header><el-card shadow="never"><el-tabs v-model="activeTab">
    <el-tab-pane label="任务池" name="tasks"><div class="toolbar task-filter-toolbar"><el-select v-model="taskFilters.source_type" clearable placeholder="来源单据" style="width: 160px" @change="load"><el-option v-for="(label, value) in sourceTypeLabels" :key="value" :label="label" :value="value" /></el-select><el-select v-model="taskFilters.task_type" clearable placeholder="任务类型" style="width: 140px" @change="load"><el-option v-for="(label, value) in taskTypeLabels" :key="value" :label="label" :value="value" /></el-select><el-select v-model="taskFilters.warehouse_id" clearable filterable placeholder="仓库" style="width: 220px" @change="load"><el-option v-for="item in warehouses" :key="String(item.id)" :label="`${item.code} · ${item.name}`" :value="String(item.id)" /></el-select><el-select v-model="taskFilters.status" clearable placeholder="状态" style="width: 140px" @change="load"><el-option v-for="(label, value) in taskStatusLabels" :key="value" :label="label" :value="value" /></el-select><el-button @click="resetTaskFilters">重置</el-button><el-button class="create-task-button" type="primary" @click="openCreateTask">创建任务</el-button></div><div class="toolbar"><el-select v-model="sourceForm.source_type" style="width:150px"><el-option v-for="(label, value) in sourceTypeLabels" :key="value" :label="label" :value="value" /></el-select><el-input v-model="sourceForm.source_id" placeholder="来源单据号或 ID" style="width:250px" /><el-button type="success" @click="generateFromDocument">从单据自动生成任务</el-button></div><el-table v-loading="loading" :data="tasks" stripe><el-table-column label="波次选择" width="90"><template #default="scope"><el-checkbox v-if="scope.row.task_type === 'pick' && ['ready','assigned'].includes(scope.row.status)" :model-value="selectedTaskIds.includes(String(scope.row.id))" @change="(value: boolean) => toggleTask(scope.row, value)" /></template></el-table-column><el-table-column prop="task_no" label="任务号" min-width="190" /><el-table-column label="来源单据" width="130"><template #default="scope">{{ labelOf(sourceTypeLabels, scope.row.source_type) }}</template></el-table-column><el-table-column label="类型" width="110"><template #default="scope">{{ taskTypeLabel(scope.row.task_type) }}</template></el-table-column><el-table-column label="仓库" min-width="180"><template #default="scope">{{ warehouseLabel(scope.row.warehouse_id) }}</template></el-table-column><el-table-column prop="planned_quantity" label="计划数量" /><el-table-column label="已完成"><template #default="scope"><el-tag :type="yesNoTag(completedLabel(scope.row))">{{ completedLabel(scope.row) }}</el-tag></template></el-table-column><el-table-column label="序列号追踪"><template #default="scope"><el-tag :type="yesNoTag(scope.row.serial_tracking)">{{ scope.row.serial_tracking ? '是' : '否' }}</el-tag></template></el-table-column><el-table-column label="状态"><template #default="scope"><el-tag class="status-tag" :type="tagTypeOf(scope.row.status)">{{ statusLabel(scope.row.status) }}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="scope"><el-button v-if="scope.row.status === 'ready'" link type="primary" @click="move(scope.row, 'in_progress')">开始</el-button><el-button v-if="scope.row.status === 'in_progress'" link type="success" @click="move(scope.row, 'completed')">完成</el-button><el-button v-if="['ready','in_progress'].includes(scope.row.status)" link type="warning" @click="openException(scope.row)">标记异常</el-button></template></el-table-column></el-table></el-tab-pane>
    <el-tab-pane label="波次" name="waves"><div class="toolbar"><el-select :model-value="waveWarehouseId" placeholder="波次仓库" clearable filterable style="width: 220px" @update:model-value="changeWaveWarehouse"><el-option v-for="item in warehouses" :key="String(item.id)" :label="`${item.code} · ${item.name}`" :value="String(item.id)" /></el-select><el-select v-model="selectedTaskIds" multiple collapse-tags clearable :disabled="!waveWarehouseId || !waveTaskOptions.length" placeholder="选择可拣货任务" style="width: 320px"><el-option v-for="item in waveTaskOptions" :key="String(item.id)" :label="`${item.task_no} · ${item.planned_quantity}`" :value="String(item.id)" /></el-select><el-button type="primary" :disabled="!waveWarehouseId || !selectedTaskIds.length" @click="createWave">创建波次</el-button></div><el-alert v-if="waveWarehouseId && !waveTaskOptions.length" title="当前仓库暂无可加入波次的待执行拣货任务，请先在任务池创建或准备拣货任务。" type="info" :closable="false" /><el-table :data="waves" stripe><el-table-column prop="wave_no" label="波次号" /><el-table-column label="仓库"><template #default="scope">{{ warehouseLabel(scope.row.warehouse_id) }}</template></el-table-column><el-table-column prop="task_count" label="任务数" /><el-table-column label="状态"><template #default="scope"><el-tag :type="tagTypeOf(scope.row.status)">{{ statusLabel(scope.row.status) }}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="scope"><el-button v-if="scope.row.status === 'draft'" link type="primary" @click="releaseWave(scope.row)">发布</el-button></template></el-table-column></el-table></el-tab-pane>
    <el-tab-pane label="异常" name="exceptions"><el-table v-if="exceptions.length" :data="exceptions" stripe><el-table-column prop="task_no" label="任务号" /><el-table-column prop="exception_reason" label="异常原因" /><el-table-column label="状态"><template #default="scope"><el-tag :type="tagTypeOf(scope.row.status)">{{ statusLabel(scope.row.status) }}</el-tag></template></el-table-column></el-table><el-empty v-else description="当前没有异常任务" /></el-tab-pane>
  </el-tabs></el-card><el-dialog v-model="createTaskVisible" title="创建任务" width="520px"><el-form label-width="110px"><el-form-item label="任务类型" required><el-select v-model="form.task_type" style="width: 100%"><el-option v-for="item in Object.keys(taskTypeLabels)" :key="item" :label="taskTypeLabel(item)" :value="item" /></el-select></el-form-item><el-form-item label="仓库" required><el-select v-model="form.warehouse_id" placeholder="请选择仓库" clearable filterable style="width: 100%"><el-option v-for="item in warehouses" :key="String(item.id)" :label="`${item.code} · ${item.name}`" :value="String(item.id)" /></el-select></el-form-item><el-form-item label="物料"><el-select v-model="form.material_id" placeholder="物料（可选）" clearable filterable style="width: 100%"><el-option v-for="item in materials" :key="String(item.id)" :label="`${item.code} · ${item.name}`" :value="String(item.id)" /></el-select></el-form-item><el-form-item label="计划数量"><el-input-number v-model="form.planned_quantity" :min="0" style="width: 100%" /></el-form-item><el-form-item label="序列号追踪"><el-checkbox v-model="form.serial_tracking">启用序列号追踪</el-checkbox></el-form-item></el-form><template #footer><el-button @click="createTaskVisible = false">取消</el-button><el-button type="primary" :loading="saving" :disabled="!form.warehouse_id" @click="save">创建任务</el-button></template></el-dialog><el-dialog v-model="exceptionVisible" title="标记异常" width="520px"><el-form label-position="top"><el-form-item label="异常原因" required><el-input v-model="exceptionReason" autofocus placeholder="请输入异常原因" /></el-form-item></el-form><template #footer><el-button @click="exceptionVisible = false">取消</el-button><el-button type="warning" :loading="exceptionSaving" @click="submitException">确定</el-button></template></el-dialog></section>
</template>
<style scoped>.page-stack{display:flex;flex-direction:column;gap:16px}.page-heading{display:flex;justify-content:space-between;align-items:flex-end}.page-heading small{color:var(--erp-muted-text);letter-spacing:.08em}.page-heading h1{margin:4px 0}.page-heading p{margin:0;color:var(--erp-muted-text)}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:12px}.task-filter-toolbar .create-task-button{margin-left:auto}.status-tag{border-width:1px}</style>
